#!/usr/bin/env bash
# usage: keybind-cheatsheet.sh [--markdown]
#
# Searchable keybind cheatsheet (SUPER+/): parses the hl.bind() lines straight
# out of ~/.config/hypr/hyprland.lua, so it never goes stale, and shows them in
# rofi. A bind's description (or trailing -- comment) is its text. With
# --markdown it prints docs/design/shell-and-bars/keybinds.md to stdout
# instead; the committed file is generated by that call, so regenerate it after
# touching a bind (the exact command is printed at the top of the doc).
#
#   --markdown    print the markdown table to stdout instead of opening rofi
#   -h, --help    this text
#
# env: KEYBIND_CONF=path   parse that file instead of ~/.config/hypr/hyprland.lua
#
# exit: 0 ok · 1 parse failed · 2 bad usage
# see: docs/design/shell-and-bars/keybinds.md

case "${1:-}" in
  "" | --markdown) ;;
  -h | --help)
    sed -n '2,/^$/p' "$0" | sed 's/^# \{0,1\}//'
    exit 0
    ;;
  *)
    sed -n '2s/^# \{0,1\}//p' "$0" >&2
    exit 2
    ;;
esac
set -uo pipefail
CONF="${KEYBIND_CONF:-$HOME/.config/hypr/hyprland.lua}"
MODE="${1:-menu}"

menu() {
  rofi -dmenu -i -p "keybinds" -theme-str 'window { width: 780px; } listview { lines: 16; }'
}

emit() {
  python3 - "$CONF" "$MODE" <<'PY'
import re, sys

conf, mode = sys.argv[1], sys.argv[2]
rows = []            # (key, description, runs)
for raw in open(conf, encoding="utf-8"):
    line = raw.strip()
    if "hl.bind(" not in line or line.startswith("--"):
        continue
    body = line[line.index("hl.bind(") + 8:]
    body = body.replace('mainMod .. " + ', '"SUPER + ')
    if ' .. ' in body or 'switch:' in body:   # loop-generated / lid-switch binds
        continue
    m = re.match(r'"([^"]+)"\s*,\s*(.*)$', body)
    if not m:
        continue
    key, rest = m.groups()
    cm = re.search(r'\)\s*--\s*(.*)$', rest)
    if cm:
        desc = cm.group(1).strip()
        rest = rest[:cm.start()] + ")"
    else:
        desc = ""
    a = re.sub(r',\s*\{[^}]*\}\s*\)*\s*$', '', rest)   # bind opts ({ repeating = ..., description = ... })
    while a.endswith(")") and a.count(")") > a.count("("):   # hl.bind's own closing paren(s)
        a = a[:-1].rstrip()
    a = a.replace("hl.dsp.", "")
    em = re.match(r'exec_cmd\("(.*)"\)$', a)
    if em:
        a = em.group(1)
        fb = re.match(r'command -v \S+ >[^&]*&&\s*(.*?)\s*\|\|', a)
        if fb:
            a = fb.group(1)                             # primary of a fallback chain
    a = a.replace("$HOME/.local/bin/", "").replace('\\"', '"')
    rows.append((key, desc or a, a))

rows += [
    ("SUPER + 1-9,0",         "switch to workspace 1-10",          "focus({ workspace = i })"),
    ("SUPER + SHIFT + 1-9,0", "move window to workspace 1-10",     "window.move({ workspace = i })"),
    ("SUPER + drag LMB/RMB",  "move / resize window",              "window.drag() / window.resize()"),
    ("SUPER + scroll",        "cycle workspaces",                  "focus({ workspace = \"e±1\" })"),
]

if mode == "--markdown":
    def cell(s):
        return s.replace("|", "\\|")
    print("# Keybinds")
    print()
    print("[Design](../README.md) › [Shell & bars](README.md) › Keybinds")
    print()
    print("`SUPER` is the mod key.")
    print("This table is generated from the `-- comment` on each `hl.bind(...)` line in `dotfiles/.config/hypr/hyprland.lua` by `keybind-cheatsheet.sh --markdown`, the same parser behind the live `SUPER+/` cheatsheet.")
    print("Do not edit it by hand: regenerate it after changing a bind.")
    print()
    print("```sh")
    print("KEYBIND_CONF=dotfiles/.config/hypr/hyprland.lua dotfiles/.local/bin/keybind-cheatsheet.sh --markdown > docs/design/shell-and-bars/keybinds.md")
    print("```")
    print()
    print("Each bind also carries a `description` flag, so `hyprctl binds` lists the same text live.")
    print("Scripts in the Runs column live in `dotfiles/.local/bin/`, which `modules/desktop.nix` links to `~/.local/bin`.")
    print("Dispatchers are `hl.dsp.*` from the [Hyprland Lua API](https://wiki.hypr.land/Configuring/).")
    print("The session itself is described in [the Hyprland README](../../../dotfiles/.config/hypr/README.md).")
    print()
    print("## Quick answers")
    print()
    print("| Topic | Answer |")
    print("|---|---|")
    print("| Fullscreen | `SUPER+F` toggles it. A window rule forces games matching `cs2\\|steam_app_*` fullscreen, and `SUPER+F` still leaves it. |")
    print("| Layouts | dwindle is the default. `SUPER+ALT+L` swaps in the scrolling layout, windows on a horizontal tape, until the next config reload. There `SUPER+CTRL+←/→` scroll by a column, `+SHIFT` swaps columns, `SUPER+CTRL+F` fits and `SUPER+CTRL+P` gives a window its own column. On dwindle the same `SUPER+CTRL+←/→` keys resize. |")
    print("| Overview | `` SUPER+` `` needs the hyprtasking plugin: the `hyprland-plugin-hyprtasking` package from the `[dram]` repo I build, loaded by `hl.plugin.load` in `hyprland.lua`. `dram update` keeps it in step with Hyprland. |")
    print("| Keyboard EN/RU | Left `Alt`+left `Shift` in either order, `SUPER+ALT+SPACE`, or a click on the EN/RU word on the bar. Right Alt and Shift do nothing. `kb-layout.sh` switches each keyboard at once, and shortcuts keep working under RU. |")
    print("| Lock | `SUPER+L`; the layout toggle is `SUPER+ALT+L`. The power menu on `SUPER+X` can lock too. |")
    print("| Bar hidden | `SUPER+SHIFT+B` toggles waybar by hand and pauses the fullscreen auto-hide until it is pressed again. |")
    print()
    print("## Binds")
    print()
    print("| Key | Action | Runs |")
    print("|---|---|---|")
    for k, d, r in rows:
        print(f"| `{cell(k)}` | {cell(d)} | `{cell(r)}` |")
else:
    w = max(len(k) for k, _, _ in rows)
    for k, d, _ in rows:
        print(f"{k:<{w}}   {d}")
PY
}

if [ "$MODE" = "--markdown" ]; then
  emit
else
  emit | menu >/dev/null
fi
